faltan = []
for es, en in PARES:
    if es not in s:
        faltan.append(es[:90])
        continue
    s = s.replace(es, en)
(raiz / 'en' / 'index.html').write_text(s, encoding='utf-8')
if faltan:
    print('Frases que ya no están en index.html (revisa su traducción):')
    for f in faltan: print('  -', f)
    sys.exit(1)
